#!/usr/bin/env node
/**
 * tests/adversarial-ui-m5-tv-stress.js
 * 
 * Milestone UI-M5 On-Device Adversarial Stress & Memory Stability Suite
 * Target: Physical LG 32LR686BPSA (webOS 8.5.0 / webOS 23, Firmware 13.50.44, IP: 192.168.1.15:9922)
 * Application: com.cinejoy.tv
 * Service: com.cinejoy.tv.service
 * Runtime: Linux 5.4.96 aarch64, Node.js v12.22.2, Chromium ~108 WAM
 * 
 * Empirical Adversarial Stress Dimensions:
 * 1. Spatial D-pad navigation across real TV views:
 *    - Top pill navigation (Home, Movies, Series, Search)
 *    - Hero banner navigation & button focus (Play Now, Details)
 *    - Horizontal shelves traversal (10+ rapid ArrowRight/ArrowLeft, auto-scrolling translation)
 *    - Virtual keyboard in search view (grid navigation, typing, results grid entry, Back key exit)
 *    - Details overlay modal (activation, modal focus trapping, cast rail, clean Back key dismissal)
 * 2. Player controls and rapid burst seeking (±15s rapid bursts) on live stream playback:
 *    - Stream resolution & live playback startup
 *    - Rapid forward seek bursts (+15s x 5 bursts in 250ms) without waiting for intermediate buffering
 *    - Rapid backward seek bursts (-15s x 5 bursts in 250ms)
 *    - Seek recovery latency (< 4.0s) & buffer continuity
 *    - OSD HUD toggle, Play/Pause remote toggle, and clean Back key teardown
 * 3. Memory stability (<75MB webOS threshold) and absence of WAM crashes or memory leaks:
 *    - Baseline VmRSS, VmHWM, and TV free memory
 *    - 10-cycle view transition & playback stress loop
 *    - WAM renderer delta VmRSS verification (< 75 MB webOS limit)
 *    - Background service VmRSS verification (< 50 MB)
 *    - System free RAM verification (> 200 MB)
 *    - Kernel dmesg & WAM process PID crash audit (zero crashes, zero segfaults)
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const CONFIG = {
  tvIp: '192.168.1.15',
  sshPort: '9922',
  sshUser: 'prisoner',
  sshKey: '/home/prem/.ssh/lg-tv_webos_rsa',
  sshKeyFallback: '/home/prem/.ssh/lg-tv_webos_decrypted',
  devtoolsPort: 9998,
  aresDevice: 'lg-tv',
  appId: 'com.cinejoy.tv',
  serviceId: 'com.cinejoy.tv.service',
  wamMaxRssDeltaMb: 75.0,
  serviceMaxRssMb: 50.0,
  minFreeRamMb: 200.0,
  resultsPath: path.resolve(__dirname, '../reports/challenger-ui-m5-tv-results.json')
};

// ANSI Color Helpers
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  red: '\x1b[31m',
  magenta: '\x1b[35m'
};

function banner(title) {
  const line = '═'.repeat(76);
  console.log(`\n${C.cyan}${C.bold}${line}`);
  console.log(`   ${title}`);
  console.log(`${line}${C.reset}\n`);
}

function pass(msg, durationMs) {
  const d = durationMs !== undefined ? ` ${C.dim}(${durationMs}ms)${C.reset}` : '';
  console.log(`  ${C.green}✔ PASS${C.reset} ${msg}${d}`);
}

function fail(msg, err) {
  console.error(`  ${C.red}✖ FAIL${C.reset} ${msg}`);
  if (err) console.error(`    ${C.red}${err.stack || err}${C.reset}`);
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// SSH Execution Helper
function execSsh(remoteCmd) {
  const activeKey = fs.existsSync(CONFIG.sshKey) ? CONFIG.sshKey : CONFIG.sshKeyFallback;
  const stdout = execSync(
    `ssh -tt -p ${CONFIG.sshPort} -i ${activeKey} -o HostKeyAlgorithms=+ssh-rsa -o PubkeyAcceptedKeyTypes=+ssh-rsa -o StrictHostKeyChecking=no -o ConnectTimeout=10 ${CONFIG.sshUser}@${CONFIG.tvIp} "${remoteCmd.replace(/"/g, '\\"')}"`,
    { encoding: 'utf8', timeout: 30000 }
  );
  return stdout;
}

// Query Memory via SSH
function queryTvMemory() {
  const meminfo = execSsh('cat /proc/meminfo');
  let memTotal = 0;
  let memFree = 0;
  let memAvailable = 0;

  meminfo.split('\n').forEach(line => {
    if (line.startsWith('MemTotal:')) memTotal = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemFree:')) memFree = parseInt(line.split(/\s+/)[1], 10) / 1024;
    if (line.startsWith('MemAvailable:')) memAvailable = parseInt(line.split(/\s+/)[1], 10) / 1024;
  });

  // Query WAM renderer process
  const psOut = execSsh("ps -o pid,user,comm,rss,args -A | grep -E 'WebAppMgr.*renderer.*client-id' | grep -v grep || true");
  let wamRendererPid = null;
  let wamRendererRssMb = 0;

  const wamMatch = psOut.trim().split('\n').filter(Boolean);
  if (wamMatch.length > 0) {
    const parts = wamMatch[0].trim().split(/\s+/);
    wamRendererPid = parts[0];
    wamRendererRssMb = (parseInt(parts[3], 10) / 1024) || 0;
  }

  // Query service process
  let servicePid = null;
  let serviceRssMb = 0;
  try {
    const sOut = execSsh(`pidof ${CONFIG.serviceId} || true`);
    const p = sOut.match(/\b\d+\b/);
    if (p) {
      servicePid = p[0];
      const sStat = execSsh(`cat /proc/${servicePid}/status | grep -E 'VmRSS|VmHWM' || true`);
      sStat.split('\n').forEach(line => {
        if (line.startsWith('VmRSS:')) serviceRssMb = parseInt(line.split(/\s+/)[1], 10) / 1024;
      });
    }
  } catch (_) {}

  return {
    memTotalMb: parseFloat(memTotal.toFixed(2)),
    memFreeMb: parseFloat(memFree.toFixed(2)),
    memAvailableMb: parseFloat(memAvailable.toFixed(2)),
    wamRendererPid,
    wamRendererRssMb: parseFloat(wamRendererRssMb.toFixed(2)),
    servicePid,
    serviceRssMb: parseFloat(serviceRssMb.toFixed(2))
  };
}

// Minimal robust CDP Client using globalThis.WebSocket
class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.ws = null;
    this.id = 1;
    this.pending = new Map();
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.wsUrl);
      this.ws.onopen = () => resolve();
      this.ws.onerror = (err) => reject(err);
      this.ws.onclose = () => {
        for (const [id, { reject: rej }] of this.pending.entries()) {
          rej(new Error('WebSocket closed'));
        }
        this.pending.clear();
      };
      this.ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.id && this.pending.has(msg.id)) {
            const { resolve: res, reject: rej } = this.pending.get(msg.id);
            this.pending.delete(msg.id);
            if (msg.error) rej(new Error(msg.error.message || JSON.stringify(msg.error)));
            else res(msg.result);
          }
        } catch (e) {
          console.error('CDP parse error:', e);
        }
      };
    });
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      if (!this.ws || this.ws.readyState !== 1) {
        return reject(new Error('WebSocket is not open'));
      }
      const msgId = this.id++;
      this.pending.set(msgId, { resolve, reject });
      this.ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  async evaluate(expression, awaitPromise = true) {
    const res = await this.send('Runtime.evaluate', {
      expression,
      awaitPromise,
      returnByValue: true
    });
    if (res.exceptionDetails) {
      throw new Error(
        res.exceptionDetails.exception
          ? (res.exceptionDetails.exception.description || res.exceptionDetails.exception.value)
          : 'Evaluation exception'
      );
    }
    return res.result ? res.result.value : undefined;
  }

  async dispatchKey(key, keyCode, code = key) {
    // Send standard DOM keydown and keyup via evaluate for maximum fidelity with webOS keycode mappings
    return await this.evaluate(`(() => {
      const eDown = new KeyboardEvent('keydown', {
        key: '${key}',
        code: '${code}',
        keyCode: ${keyCode},
        which: ${keyCode},
        bubbles: true,
        cancelable: true
      });
      document.dispatchEvent(eDown);
      const eUp = new KeyboardEvent('keyup', {
        key: '${key}',
        code: '${code}',
        keyCode: ${keyCode},
        which: ${keyCode},
        bubbles: true,
        cancelable: true
      });
      document.dispatchEvent(eUp);
      return {
        activeId: document.activeElement ? (document.activeElement.id || document.activeElement.className) : null
      };
    })()`);
  }

  close() {
    if (this.ws) {
      try { this.ws.close(); } catch (_) {}
      this.ws = null;
    }
  }
}

async function connectToWam(maxRetries = 15, delayMs = 1000) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const res = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`);
      const pages = await res.json();
      const target = pages.find(p => p.url && p.url.includes(CONFIG.appId));
      if (target && target.webSocketDebuggerUrl) {
        const client = new CdpClient(target.webSocketDebuggerUrl);
        await client.connect();
        await client.send('Runtime.enable');
        return { client, target };
      }
    } catch (_) {}
    if (attempt < maxRetries) await sleep(delayMs);
  }
  throw new Error(`Failed to connect to WAM DevTools target for ${CONFIG.appId} on ${CONFIG.tvIp}:${CONFIG.devtoolsPort}`);
}

async function runEmpiricalStressSuite() {
  banner('CHALLENGER 2: EMPIRICAL ADVERSARIAL STRESS & MEMORY STABILITY SUITE (UI-M5)');
  console.log(`  Target TV: ${CONFIG.tvIp}:${CONFIG.sshPort} (LG 32LR686BPSA, webOS 8.5.0)`);
  console.log(`  App ID:    ${CONFIG.appId}`);
  console.log(`  Service:   ${CONFIG.serviceId}`);
  console.log(`  Timestamp: ${new Date().toISOString()}\n`);

  const results = {
    timestamp: new Date().toISOString(),
    verdict: 'PENDING',
    target: {},
    baselineMemory: {},
    finalMemory: {},
    checks: [],
    stressTelemetry: {}
  };

  async function check(category, testId, title, fn) {
    const t0 = Date.now();
    try {
      const data = await fn();
      const elapsed = Date.now() - t0;
      pass(`[${category}] [${testId}] ${title}`, elapsed);
      results.checks.push({ category, testId, title, passed: true, elapsed, data });
      return data;
    } catch (err) {
      const elapsed = Date.now() - t0;
      fail(`[${category}] [${testId}] ${title}`, err);
      results.checks.push({ category, testId, title, passed: false, elapsed, error: err.message });
      throw err;
    }
  }

  let cdpClient = null;

  try {
    // =========================================================================
    // SECTION 0: PRE-FLIGHT HARDWARE & MEMORY BASELINE
    // =========================================================================
    banner('SECTION 0: HARDWARE reachability & MEMORY BASELINE');

    await check('BASELINE', 'HW-01', 'Verify LG webOS TV Reachability & Hardware Spec', async () => {
      const info = execSsh('cat /etc/os-release && uname -a');
      if (!info.includes('webos')) throw new Error('Target is not a webOS device');
      results.target.osInfo = info.split('\n')[0];
      return { info: info.split('\n')[0] };
    });

    const baselineMem = queryTvMemory();
    results.baselineMemory = baselineMem;
    console.log(`  ${C.blue}ℹ Baseline Memory:${C.reset} Free RAM: ${baselineMem.memAvailableMb} MB | WAM Renderer PID: ${baselineMem.wamRendererPid} (RSS: ${baselineMem.wamRendererRssMb} MB) | Service PID: ${baselineMem.servicePid} (RSS: ${baselineMem.serviceRssMb} MB)\n`);

    await check('BASELINE', 'HW-02', 'Connect to Live WAM Chromium DevTools Target', async () => {
      const { client, target } = await connectToWam();
      cdpClient = client;
      return { pageId: target.id, url: target.url };
    });

    // Bring app to Home view to start clean
    await cdpClient.evaluate(`(() => {
      if (window.CinejoyApp) {
        window.CinejoyApp.switchView('home');
      }
    })()`);
    await sleep(600);

    // =========================================================================
    // SECTION 1: SPATIAL D-PAD NAVIGATION STRESS ACROSS VIEWS
    // =========================================================================
    banner('SECTION 1: SPATIAL D-PAD NAVIGATION STRESS ACROSS REAL TV VIEWS');

    // 1.1 Top Pill Navigation
    await check('SPATIAL_NAV', 'DPAD-01', 'Top Pill Navigation Traversal across Home, Movies, Series, Search', async () => {
      // Focus header nav home
      const navStatus = await cdpClient.evaluate(`(() => {
        const homeTab = document.getElementById('header-nav-home');
        if (window.SpatialNav) window.SpatialNav.setFocus(homeTab);
        return {
          currentFocusId: document.activeElement ? document.activeElement.id : null,
          hasActiveClass: homeTab.classList.contains('focused') || homeTab.classList.contains('active')
        };
      })()`);

      if (navStatus.currentFocusId !== 'header-nav-home') {
        throw new Error(`Expected focus on header-nav-home, got: ${navStatus.currentFocusId}`);
      }

      // Step right across tabs
      const steps = [
        { key: 'ArrowRight', code: 39, expected: 'header-nav-movies' },
        { key: 'ArrowRight', code: 39, expected: 'header-nav-series' },
        { key: 'ArrowRight', code: 39, expected: 'header-nav-search' },
        { key: 'ArrowLeft', code: 37, expected: 'header-nav-series' },
        { key: 'ArrowLeft', code: 37, expected: 'header-nav-movies' },
        { key: 'ArrowLeft', code: 37, expected: 'header-nav-home' }
      ];

      for (const step of steps) {
        await cdpClient.dispatchKey(step.key, step.code);
        await sleep(100);
        const focusId = await cdpClient.evaluate(`document.activeElement ? document.activeElement.id : null`);
        if (focusId !== step.expected) {
          throw new Error(`Step ${step.key} failed: expected ${step.expected}, got ${focusId}`);
        }
      }

      return { stepsCompleted: steps.length };
    });

    // 1.2 Hero Banner Navigation
    await check('SPATIAL_NAV', 'DPAD-02', 'Hero Banner Navigation & Button Focus Transition', async () => {
      // From header-nav-home, press ArrowDown to enter Hero Banner
      await cdpClient.dispatchKey('ArrowDown', 40);
      await sleep(150);

      const heroFocus = await cdpClient.evaluate(`(() => {
        const el = document.activeElement;
        const playBtn = document.getElementById('hero-play-btn');
        return {
          id: el ? el.id : null,
          navGroup: el ? el.getAttribute('data-nav-group') : null,
          isHeroPlay: el === playBtn,
          hasFocusedClass: el ? el.classList.contains('focused') : false
        };
      })()`);

      if (!heroFocus.isHeroPlay && heroFocus.navGroup !== 'hero') {
        throw new Error(`Focus did not enter Hero Banner buttons: ${JSON.stringify(heroFocus)}`);
      }

      // Navigate right inside hero action group to Details button
      await cdpClient.dispatchKey('ArrowRight', 39);
      await sleep(120);

      const heroDetails = await cdpClient.evaluate(`(() => {
        const el = document.activeElement;
        return { id: el ? el.id : null, navGroup: el ? el.getAttribute('data-nav-group') : null };
      })()`);

      if (heroDetails.id !== 'hero-details-btn' && heroDetails.navGroup !== 'hero') {
        throw new Error(`Focus did not move to hero details button: ${JSON.stringify(heroDetails)}`);
      }

      return { heroFocus, heroDetails };
    });

    // 1.3 Horizontal Shelves Traversal & Rapid Auto-Scrolling
    await check('SPATIAL_NAV', 'DPAD-03', 'Horizontal Shelves Traversal: 10 Rapid ArrowRight + Left Bursts', async () => {
      // Navigate down into the first content shelf
      await cdpClient.dispatchKey('ArrowDown', 40);
      await sleep(150);
      await cdpClient.dispatchKey('ArrowDown', 40);
      await sleep(150);

      const shelfState = await cdpClient.evaluate(`(() => {
        const el = document.activeElement;
        const shelf = el ? el.closest('.content-shelf') : null;
        return {
          activeId: el ? (el.id || el.className) : null,
          shelfId: shelf ? shelf.id : null,
          isCard: el ? el.classList.contains('card-poster') || el.classList.contains('card-provider') : false
        };
      })()`);

      if (!shelfState.isCard && !shelfState.shelfId) {
        throw new Error(`Focus did not enter content shelf cards: ${JSON.stringify(shelfState)}`);
      }

      // Execute 10 rapid ArrowRight presses (burst stress)
      const burstRightLogs = [];
      for (let i = 0; i < 10; i++) {
        await cdpClient.dispatchKey('ArrowRight', 39);
        await sleep(50); // fast repeat
      }
      await sleep(200);

      const postRightState = await cdpClient.evaluate(`(() => {
        const el = document.activeElement;
        const rail = el ? el.closest('.shelf-rail') : null;
        const transform = rail ? window.getComputedStyle(rail).transform : '';
        return {
          title: el ? (el.getAttribute('data-title') || el.className) : null,
          railTransform: transform
        };
      })()`);

      // Execute 10 rapid ArrowLeft presses back to shelf origin
      for (let i = 0; i < 10; i++) {
        await cdpClient.dispatchKey('ArrowLeft', 37);
        await sleep(50);
      }
      await sleep(200);

      const postLeftState = await cdpClient.evaluate(`(() => {
        const el = document.activeElement;
