await check('MEDIA_PLAYER', 'SEEK-01', 'Live Stream Playback Startup via On-Device Loopback Proxy', async () => {
  // Launch Fight Club playback on TV
  await cdpClient.evaluate(`(() => {
    if (window.CinejoyApp) window.CinejoyApp.switchView('player');
    return window.PlayerController.loadStream({ tmdbId: 550, title: 'Fight Club', type: 'movie' }, 'secret');
  })()`);

  // Poll until video starts playing (readyState >= 3)
  let videoReady = false;
  const tStart = Date.now();
  let status = {};

  for (let attempt = 0; attempt < 18; attempt++) {
    await sleep(1000);
    status = await cdpClient.evaluate(`(() => {
      const v = document.getElementById('main-video-player');
      if (!v) return { found: false };
      return {
        found: true,
        readyState: v.readyState,
        paused: v.paused,
        currentTime: v.currentTime,
        duration: v.duration,
        bufferedEnd: (v.buffered && v.buffered.length > 0) ? v.buffered.end(v.buffered.length - 1) : 0,
        state: window.PlayerController ? window.PlayerController.state : null,
        error: v.error ? v.error.message : null
      };
    })()`);

    if (status.readyState >= 3) {
      videoReady = true;
      break;
    }
  }

  if (!videoReady) {
    throw new Error(`Video failed to reach readyState >= 3 within 18s. Final state: ${JSON.stringify(status)}`);
  }

  // Ensure playback is active
  await cdpClient.evaluate(`window.PlayerController.play()`);
  await sleep(2000);

  const playingStatus = await cdpClient.evaluate(`(() => {
    const v = document.getElementById('main-video-player');
    return {
      currentTime: v.currentTime,
      paused: v.paused,
      readyState: v.readyState,
      duration: v.duration,
      bufferedEnd: (v.buffered && v.buffered.length > 0) ? v.buffered.end(v.buffered.length - 1) : 0
    };
  })()`);

  return {
    loadDurationMs: Date.now() - tStart,
    readyState: playingStatus.readyState,
    currentTime: playingStatus.currentTime,
    duration: playingStatus.duration,
    bufferedEnd: playingStatus.bufferedEnd
  };
});

