await check('MEDIA_PLAYER', 'SEEK-01', 'Live Stream Playback Startup via On-Device Loopback Proxy', async () => {
  // Launch Fight Club playback on TV
  const playRes = await cdpClient.evaluate(`(async () => {
    if (!window.PlayerController) return { error: 'No PlayerController' };
    window.PlayerController.init();
    const item = {
      id: 550,
      tmdbId: 550,
      title: 'Fight Club',
      type: 'movie',
      server: 'secret'
    };
    // Switch to player view
    if (window.CinejoyApp) window.CinejoyApp.switchView('player');
    await window.PlayerController.loadStream(item, 'secret');
    return { initiated: true };
  })()`);

  // Poll until video starts playing (readyState >= 3, currentTime > 0)
  let videoReady = false;
  const tStart = Date.now();
  let status = {};

  while (Date.now() - tStart < 15000) {
    status = await cdpClient.evaluate(`(() => {
      const v = document.getElementById('main-video-player');
      if (!v) return { found: false };
      return {
        found: true,
        readyState: v.readyState,
        paused: v.paused,
        currentTime: v.currentTime,
        duration: v.duration,
        bufferedEnd: (v.buffered && v.buffered.length > 0) ? v.buffered.end(v.buffered.length - 1) : 0,
        error: v.error ? v.error.message : null
      };
    })()`);

    if (status.readyState >= 3 && status.currentTime > 0) {
      videoReady = true;
      break;
    }
    await sleep(500);
  }

  if (!videoReady) {
    throw new Error(`Video failed to start playback within 15s. Final state: ${JSON.stringify(status)}`);
  }

  return {
    loadDurationMs: Date.now() - tStart,
    readyState: status.readyState,
    currentTime: status.currentTime,
    duration: status.duration,
    bufferedEnd: status.bufferedEnd
  };
});

