// Engage modal trap on details view
await cdpClient.evaluate(`(() => {
  const detailsView = document.getElementById('view-details');
  if (window.SpatialNav && detailsView) {
    window.SpatialNav.trap(detailsView);
  }
})()`);

// Assert modal focus containment: 5 rapid ArrowUp hammering presses must NOT escape to header
for (let i = 0; i < 5; i++) {
  await cdpClient.dispatchKey('ArrowUp', 38);
  await sleep(60);
}

const trapCheck = await cdpClient.evaluate(`(() => {
  const el = document.activeElement;
  const isTrapped = window.SpatialNav ? window.SpatialNav.isTrapped() : false;
  return {
    id: el ? el.id : null,
    isTrapped,
    isInDetails: el ? Boolean(el.closest('#view-details')) : false,
    isHeader: el ? Boolean(el.closest('#app-header')) : false
  };
})()`);

if (trapCheck.isHeader) {
  throw new Error('Focus escaped Details modal to Header under ArrowUp pressure!');
}

// Dismiss Details modal using Back Key / Untrap
await cdpClient.dispatchKey('Escape', 27);
await sleep(400);

const afterBackState = await cdpClient.evaluate(`(() => {
  if (window.SpatialNav && window.SpatialNav.isTrapped()) {
    window.SpatialNav.untrap();
  }
  if (window.CinejoyApp) {
    window.CinejoyApp.switchView('home');
  }
  const detailsView = document.getElementById('view-details');
  const homeView = document.getElementById('view-home');
  return {
    detailsActive: detailsView ? detailsView.classList.contains('active') : false,
    homeActive: homeView ? homeView.classList.contains('active') : false,
    currentFocus: document.activeElement ? (document.activeElement.id || document.activeElement.className) : null
  };
})()`);

